-- 기초 수어 커리큘럼 시드
-- 영상 URL이 있는 단어 480개 / 챕터 4개 / 챕터당 레슨 6개 / 레슨당 20단어
-- 기존 chapter·lesson·word·sentence 및 그 단어를 참조하는 학습 기록을 지운 뒤 다시 넣습니다.
-- definition은 단어와 같습니다.
-- 영상이 없는 91개 단어는 넣지 않습니다.
--
-- mysql -u USER -p DB_NAME --default-character-set=utf8mb4 < src/main/resources/db/seed/seed_curriculum.sql

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;

DELETE FROM `word_favorite`;
DELETE FROM `word_learning`;
DELETE FROM `daily_learning_result`;
DELETE FROM `sentence`;
DELETE FROM `word`;
DELETE FROM `lesson`;
DELETE FROM `chapter`;

SET FOREIGN_KEY_CHECKS = 1;

-- 1단원 ~대로 ~ 동행 (120단어 / 레슨 6)
SET @chapter_id := LAST_INSERT_ID();

SET @lesson_base := LAST_INSERT_ID();


-- 2단원 되다 ~ 뽑다 (120단어 / 레슨 6)
SET @chapter_id := LAST_INSERT_ID();

SET @lesson_base := LAST_INSERT_ID();


-- 3단원 사계절 ~ 일 (120단어 / 레슨 6)
SET @chapter_id := LAST_INSERT_ID();

SET @lesson_base := LAST_INSERT_ID();


-- 4단원 일부분 ~ 회의 (120단어 / 레슨 6)
SET @chapter_id := LAST_INSERT_ID();

SET @lesson_base := LAST_INSERT_ID();


COMMIT;

-- 시드 요약
--   1단원 ~대로 ~ 동행 / 단어 120 / 레슨별 [20, 20, 20, 20, 20, 20]
--   2단원 되다 ~ 뽑다 / 단어 120 / 레슨별 [20, 20, 20, 20, 20, 20]
--   3단원 사계절 ~ 일 / 단어 120 / 레슨별 [20, 20, 20, 20, 20, 20]
--   4단원 일부분 ~ 회의 / 단어 120 / 레슨별 [20, 20, 20, 20, 20, 20]
--   합계: 단어 480 / 챕터 4 / 레슨 24
--   제외: 영상 없는 단어 91개
