INSERT INTO `chapter` (`title`, `description`, `order_number`, `created_at`, `updated_at`) VALUES
  ('1단원 ~대로 ~ 동행', '영상 있는 기초 수어 (~대로 ~ 동행, 120단어)', 1, NOW(), NOW());
INSERT INTO `lesson` (`lesson_name`, `chapter_id`, `order_number`, `description`, `created_at`, `updated_at`) VALUES
  ('~대로 ~ 건강', @chapter_id, 1, '20단어: ~대로, ~보다, 가깝다, 가능, 가다, 가득하다, 가방, 가입, 가정, 가져오다, 가족, 가지다, 각각, 간단하다, 갑자기, 강하다, 같다, 개인, 걱정, 건강', NOW(), NOW()),
  ('검사 ~ 공부', @chapter_id, 2, '20단어: 검사, 검정, 결국, 결석, 결정, 결혼, 겸손, 경쟁, 경험, 계산, 계약, 계획, 고르다, 고민, 고장, 곳, 공감, 공공, 공범, 공부', NOW(), NOW()),
  ('공짜 ~ 금요일', @chapter_id, 3, '20단어: 공짜, 과거, 과자, 광고, 괜찮다, 교사, 교육, 구경, 구조, 구형, 궁금하다, 귀신, 귀찮다, 그냥, 그러나, 그림, 그만두다, 글, 긁다, 금요일', NOW(), NOW()),
  ('급하다 ~ 남매', @chapter_id, 4, '20단어: 급하다, 기관, 기다리다, 기록, 기름, 기본, 기억, 기회, 길, 까지, 깨끗하다, 꼼꼼, 끓다, 나라, 나무, 나이, 나타나다, 날, 날짜, 남매', NOW(), NOW()),
  ('낫다 ~ 다행', @chapter_id, 5, '20단어: 낫다, 낯설다, 낳다, 내용, 넓다, 넘기다, 넘다, 노래, 노력, 놀다, 누구, 누르다, 눈, 느끼다, 늦다, 다니다, 다르다, 다리, 다음, 다행', NOW(), NOW()),
  ('닫다 ~ 동행', @chapter_id, 6, '20단어: 닫다, 당기다, 당황하다, 대답, 대략, 대부분, 대신, 대충, 더, 덥다, 데려오다, 도장, 도착, 독특, 돈, 돕다, 동네, 동사무소, 동시, 동행', NOW(), NOW());
