INSERT INTO `chapter` (`title`, `description`, `order_number`, `created_at`, `updated_at`) VALUES
  ('2단원 되다 ~ 뽑다', '영상 있는 기초 수어 (되다 ~ 뽑다, 120단어)', 2, NOW(), NOW());
INSERT INTO `lesson` (`lesson_name`, `chapter_id`, `order_number`, `description`, `created_at`, `updated_at`) VALUES
  ('되다 ~ 막다', @chapter_id, 1, '20단어: 되다, 되돌리다, 두다, 둘, 둘이, 들어가다, 등기, 따뜻, 따라가다, 따로, 딱맞다, 딸, 때, 또, 뜨다, 뜻밖에, 마스크, 마음에들다, 마주보다, 막다', NOW(), NOW()),
  ('만 ~ 모르다', @chapter_id, 2, '20단어: 만, 만나다, 많다, 말하다, 맛있다, 망설이다, 맞다, 맞벌이, 맞지않다, 맞추다, 맡기다, 맡다, 매일, 매주, 머무르다, 먹다, 며칠, 몇, 모두, 모르다', NOW(), NOW()),
  ('모습 ~ 바꾸다', @chapter_id, 3, '20단어: 모습, 모으다, 모임, 목적, 몰려들다, 몸, 못하다, 무엇, 문, 문장, 문제, 묻다, 물, 물건, 미래, 미루다, 미안하다, 민족, 믿다, 바꾸다', NOW(), NOW()),
  ('바닥 ~ 벌써', @chapter_id, 4, '20단어: 바닥, 바람, 바로, 바쁘다, 밖, 반찬, 발견, 발표, 밝다, 방, 방문, 방법, 방식, 방학, 배우다, 백점, 버리다, 버스, 벌, 벌써', NOW(), NOW()),
  ('법 ~ 부회장', @chapter_id, 5, '20단어: 법, 병, 병원, 보내다, 보다, 보았다, 보여주다, 보통, 보호, 복사, 복잡하다, 볼펜, 봉투, 부르다, 부모, 부부, 부족, 부탁, 부터, 부회장', NOW(), NOW()),
  ('북한 ~ 뽑다', @chapter_id, 6, '20단어: 북한, 분위기, 불가능, 불량, 불안, 붙이다, 비, 비교, 비닐, 비밀, 비슷하다, 비싸다, 비정상, 빌딩, 빠지다, 빨강, 빨리, 빼다, 뼈, 뽑다', NOW(), NOW());
