INSERT INTO `chapter` (`title`, `description`, `order_number`, `created_at`, `updated_at`) VALUES
  ('3단원 사계절 ~ 일', '영상 있는 기초 수어 (사계절 ~ 일, 120단어)', 3, NOW(), NOW());
INSERT INTO `lesson` (`lesson_name`, `chapter_id`, `order_number`, `description`, `created_at`, `updated_at`) VALUES
  ('사계절 ~ 성격', @chapter_id, 1, '20단어: 사계절, 사다, 사라지다, 사람, 사무, 사용, 살다, 삽입, 상관없다, 상담, 새롭다, 생각, 생기다, 생명, 서류, 선배, 선언, 선택, 설명, 성격', NOW(), NOW()),
  ('센터 ~ 싫다', @chapter_id, 2, '20단어: 센터, 소개, 소문, 소풍, 속하다, 손님, 손해, 수고, 순서, 숫자, 쉬다, 시간, 시스템, 시작, 시집가다, 신고, 신발, 신청, 실수, 싫다', NOW(), NOW()),
  ('심다 ~ 애매하다', @chapter_id, 3, '20단어: 심다, 심하다, 싸다, 쓰다, 씻다, 아깝다, 아니다, 아들, 아마, 아빠, 아이, 아직, 아침, 아프다, 안, 안내, 안되다, 앉다, 알다, 애매하다', NOW(), NOW()),
  ('약속 ~ 옛날', @chapter_id, 4, '20단어: 약속, 어디, 어떻게, 언제, 얼굴, 얼마, 엄마, 없다, 여동생, 여러가지, 여러번, 여전하다, 연결, 열다, 열심, 영수증, 영양, 영어, 예쁘다, 옛날', NOW(), NOW()),
  ('오늘 ~ 위험', @chapter_id, 5, '20단어: 오늘, 오다, 오래, 오직, 오후, 옮기다, 옷, 완벽, 완전, 왜, 외국, 요약, 요즘, 우편, 운동, 운영, 원하다, 월요일, 위로하다, 위험', NOW(), NOW()),
  ('유치 ~ 일', @chapter_id, 6, '20단어: 유치, 유치원, 은행, 의미, 이름, 이사, 이사하다, 이야기, 이야기하다, 이익, 이전, 이해, 이후, 인감, 인사, 인쇄, 인정, 인터넷, 인터뷰, 일', NOW(), NOW());
