INSERT INTO `chapter` (`title`, `description`, `order_number`, `created_at`, `updated_at`) VALUES
  ('4단원 일부분 ~ 회의', '영상 있는 기초 수어 (일부분 ~ 회의, 120단어)', 4, NOW(), NOW());
INSERT INTO `lesson` (`lesson_name`, `chapter_id`, `order_number`, `description`, `created_at`, `updated_at`) VALUES
  ('일부분 ~ 전달', @chapter_id, 1, '20단어: 일부분, 일요일, 일하다, 읽다, 임신, 입다, 있다, 잊다, 자녀, 자다, 자매, 자연, 자유, 작다, 잘하다, 잠깐, 장애, 저녁, 저축, 전달', NOW(), NOW()),
  ('전하다 ~ 주소', @chapter_id, 2, '20단어: 전하다, 전화하다, 점수, 정도, 정부, 정상, 제한, 조건, 조심, 조절, 좁다, 종류, 종이, 종합, 좋다, 주고받다, 주다, 주사, 주세요, 주소', NOW(), NOW()),
  ('주차 ~ 짜증', @chapter_id, 3, '20단어: 주차, 준비, 줄다, 중, 중복, 중앙, 중요, 지금, 지다, 지부, 지시, 지역, 지우다, 지하철, 직면하다, 직접, 질문, 집, 집중, 짜증', NOW(), NOW()),
  ('짧다 ~ 탈락', @chapter_id, 4, '20단어: 짧다, 찍다, 착각, 참고, 책, 처음, 초과, 출발, 출석, 춥다, 충분하다, 친구, 카드, 카페, 컴퓨터, 켜다, 크다, 키우다, 타자, 탈락', NOW(), NOW()),
  ('태도 ~ 학생', @chapter_id, 5, '20단어: 태도, 토요일, 특별, 틀리다, 파악하다, 파일, 퍼센트, 펴다, 편안하다, 포기, 포장, 폭발, 표, 필요, 필요없다, 하다, 하루, 하지마, 학교, 학생', NOW(), NOW()),
  ('한국 ~ 회의', @chapter_id, 6, '20단어: 한국, 할인, 함께, 합격, 항상, 해결, 핸드폰, 행사, 허락, 형제, 혹시, 혼자, 홈페이지, 화장실, 확실하다, 활동, 회, 회사, 회원, 회의', NOW(), NOW());
